RotateBody = { 1 => AgentID/*old*/, 2 => AgentID/*new*/, 3 => Timestamp,
               ? 4 => uint /*grace-ms, default 7 days*/ }
RevokeBody = { 1 => AgentID/*revoked*/, 2 => Timestamp,
               ? 3 => uint /*reason: 0 unspecified,1 compromise,
                             2 superseded,3 cessation*/ }
